{
  "implementation": "def solve(case):
    lines = case["lines"]
    trajectory = []
    state = "start"
    error_line = None
    valid_types = {"Thought", "Action", "Action Input", "Observation", "Final"}
    for i, line in enumerate(lines, start=1):
        if ": " in line:
            typ, content = line.split(": ", 1)
        else:
            error_line = i
            break
        if typ not in valid_types:
            error_line = i
            break
        if state == "start":
            if typ == "Thought":
                state = "after_thought"
                trajectory.append({"type": typ.lower(), "content": content})
            else:
                error_line = i
                break
        elif state == "after_thought":
            if typ == "Action":
                state = "after_action"
                trajectory.append({"type": typ.lower(), "content": content})
            elif typ == "Final":
                state = "final"
                trajectory.append({"type": typ.lower(), "content": content})
            else:
                error_line = i
                break
        elif state == "after_action":
            if typ == "Action Input":
                state = "after_action_input"
                trajectory.append({"type": typ.lower(), "content": content})
            elif typ == "Observation":
                state = "after_observation"
                trajectory.append({"type": typ.lower(), "content": content})
            else:
                error_line = i
                break
        elif state == "after_action_input":
            if typ == "Observation":
                state = "after_observation"
                trajectory.append({"type": typ.lower(), "content": content})
            else:
                error_line = i
                break
        elif state == "after_observation":
            if typ == "Thought":
                state = "after_thought"
                trajectory.append({"type": typ.lower(), "content": content})
            else:
                error_line = i
                break
        elif state == "final":
            error_line = i
            break
    if error_line is not None:
        return {"valid": False, "error_line": error_line, "trajectory": trajectory}
    if state in ("after_observation", "final"):
        return {"valid": True, "error_line": None, "trajectory": trajectory}
    else:
        # incomplete sequence; error at the last line position
        return {"valid": False, "error_line": len(lines), "trajectory": trajectory}"
}
